   89	    /**
   90	     * The surplus is spent by the mine that grows what the account is short of, before the persona's
   91	     * ship habit: the more one resource towers over the least, the more a build is the answer. The
   92	     * floor ignores mild imbalance, so a safety action (a fleetsave under a visible raid) is never
   93	     * outranked by an ordinary surplus; only a severe one — one resource hundreds of times another —
   94	     * makes the mine the answer.
   95	     */
   96	    private function buildScarcityBoost(PerceptionSnapshot $perception, float $resourceNeed): float
   97	    {
   98	        if ($resourceNeed < 1.0) {
   99	            return 0.0;
  100	        }
  101	
  102	        $metal = 0.0;
  103	        $crystal = 0.0;
  104	        $deuterium = 0.0;
  105	
  106	        foreach ($perception->planets as $planet) {
  107	            $metal += (float) ($planet['resources']['metal'] ?? 0.0);
  108	            $crystal += (float) ($planet['resources']['crystal'] ?? 0.0);
  109	            $deuterium += (float) ($planet['resources']['deuterium'] ?? 0.0);
  110	        }
  111	
  112	        $abundant = max($metal, $crystal, $deuterium);
  113	        $scarce = min($metal, $crystal, $deuterium);
  114	
  115	        // 0 below 10:1, 1.0 once one resource is 1,000x another: the scarce resource
  116	        // ranks above the persona's habit only when it really is the binding constraint.
  117	        return min(1.0, max(0.0, (log10($abundant / max(1.0, $scarce)) - 1.0) / 2.0));
  118	    }
