 10	class DecisionEngine
 11	{
 12	    public function __construct(
 13	        private CandidateActionFactory $candidateActionFactory,
 14	        private UtilityScorer $utilityScorer,
 15	        private RandomSource $randomSource,
 16	    ) {
 17	    }
 18	
 19	    public function decide(AiProfile $profile, PerceptionSnapshot $perception, string $decisionKey): DecisionTrace
 20	    {
 21	        $generation = $this->candidateActionFactory->create($perception);
 22	        $scored = $this->utilityScorer->score($profile, $generation, $decisionKey);
 23	        $selected = $this->situationalErrand(
 24	            $scored,
 25	            $this->utilityScorer->select($profile, $scored, $decisionKey),
 26	        );
 27	        $selected = $this->idleOverride(
 28	            $profile,
 29	            $perception,
 30	            $scored,
 31	            $selected,
 32	            $decisionKey,
 33	        );
 34	        $inputHash = hash('sha256', json_encode($perception->traceInput(), JSON_THROW_ON_ERROR));
 35	
 36	        return app()->makeWith(DecisionTrace::class, [
 37	            'perception' => $perception,
 38	            'candidates' => $scored,
 39	            'selected' => $selected,
 40	            'rejections' => $generation->rejections,
 41	            'inputHash' => $inputHash,
 42	        ]);
 43	    }
 44	
 45	    /**
 46	     * A login's one errand. ScheduleAiIntentAction refills the build queues and the lab in every
 47	     * session whatever wins the slot, so a chore that fills them anyway spends the errand on work
 48	     * that was going to happen — and the fleet errand the situation actually offers (a raid from a
 49	     * report, debris at home, a colony ship, an expedition) never gets picked. The best candidate
 50	     * that is neither a queue chore nor doing nothing takes the slot, unless doing nothing scores
 51	     * higher: a quiet login is still a legitimate choice.
 52	     *
 53	     * @param array<int, ScoredCandidate> $scored
 54	     */
 55	    private function situationalErrand(array $scored, ScoredCandidate $selected): ScoredCandidate
 56	    {
 57	        if (!in_array($scored[0]->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research], true)) {
 58	            return $selected;
 59	        }
 60	
 61	        $doNothing = null;
 62	        foreach ($scored as $candidate) {
 63	            if ($candidate->candidate->type === AiCandidateActionType::DoNothing) {
 64	                $doNothing = $candidate;
 65	                break;
 66	            }
 67	        }
 68	
 69	        if ($doNothing === null) {
 70	            return $selected;
 71	        }
 72	
 73	        // $scored is already ranked best first, so the first candidate past the chores is the best
 74	        // remaining one: if it cannot beat doing nothing, neither can anything ranked below it.
 75	        foreach ($scored as $candidate) {
 76	            if (in_array($candidate->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research, AiCandidateActionType::DoNothing], true)) {
 77	                continue;
 78	            }
 79	
 80	            return $candidate->score > $doNothing->score ? $candidate : $selected;
 81	        }
 82	
 83	        return $selected;
 84	    }
 85	
 86	    /**
 87	     * The rare "opened the game, did nothing, closed it" moment: a small seeded,
 88	     * skill-band-aware draw that picks DoNothing even when a real action won.
 89	     * A save or a reaction wake always wins — variance never trades away a real
 90	     * reaction (V2/V6 safety).
 91	     *
 92	     * @param array<int, ScoredCandidate> $scored
 93	     */
 94	    private function idleOverride(AiProfile $profile, PerceptionSnapshot $perception, array $scored, ScoredCandidate $selected, string $decisionKey): ScoredCandidate
 95	    {
 96	        if ($perception->fleetsaveEligible || $perception->reactionWakeAt !== null) {
 97	            return $selected;
 98	        }
 99	
100	        if ($selected->candidate->type === AiCandidateActionType::DoNothing) {
101	            return $selected;
102	        }
103	
104	        if ($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':idle') >= $profile->skill_band->idleOverrideProbability()) {
105	            return $selected;
106	        }
107	
108	        foreach ($scored as $candidate) {
109	            if ($candidate->candidate->type === AiCandidateActionType::DoNothing) {
110	                return $candidate;
111	            }
112	        }
113	
114	        return $selected;
115	    }
116	}

