  299	/**
  300	 * The cheapest host ambition this planet cannot produce yet -- the same reading the chain itself
  301	 * takes, restated from the host catalogue so the expectation is never the implementation.
  302	 */
  303	function chainCheapestUnmetAmbition(PlanetService $planet): GameObject
  304	{
  305	    $objects = [...ObjectService::getResearchObjects(), ...ObjectService::getUnitObjects()];
  306	    usort($objects, static fn (GameObject $left, GameObject $right): int => $left->price->resources->sum() <=> $right->price->resources->sum());
  307	
  308	    foreach ($objects as $object) {
  309	        foreach (ObjectService::getRecursiveRequirements($object->machine_name) as $machineName => $level) {
  310	            $current = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research
  311	                ? ($planet->getPlayer()?->getResearchLevel($machineName) ?? 0)
  312	                : $planet->getObjectLevel($machineName);
  313	
  314	            if ($current < $level) {
  315	                return $object;
  316	            }
  317	        }
  318	    }
  319	
  320	    throw new RuntimeException('the host catalogue offers no ambition this planet cannot produce');
  321	}
